{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required = set(case.get("required_symbols", []))
    by_id = {node["id"]: node for node in nodes}
    children = {}
    for node in nodes:
        parent = node.get("parent")
        if parent is not None:
            children.setdefault(parent, []).append(node["id"])

    retained = set()
    for node in nodes:
        if not node.get("removable", False) or node.get("symbol") in required:
            current = node["id"]
            while current is not None and current in by_id and current not in retained:
                retained.add(current)
                current = by_id[current].get("parent")

    changed = True
    while changed:
        changed = False
        for node in nodes:
            if node["id"] in retained:
                parent = node.get("parent")
                if parent is not None and parent in by_id and parent not in retained:
                    retained.add(parent)
                    changed = True

    return {
        "removed_node_ids": [node["id"] for node in nodes if node["id"] not in retained],
        "retained_node_ids": [node["id"] for node in nodes if node["id"] in retained],
    }"}
